{

"kind": "propose",
"summary": "Liveness probe timeout is too short for the application's startup time",
"hypotheses": [
  {
    "root_cause_class": "probe_too_strict_for_startup",
    "summary": "Liveness probe timeout (1s) is too short for the application's startup time (32s).",
    "supporting": ["probe_kills", "killed_during_startup", "ev-container_logs_tail"],
    "contradicting": ["probe_timeouts"],
    "missing": [],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "finance",
    "name": "ledger",
    "uid": "uid-deployment-ledger"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 30
    }
  },
  "expected_effect": "Extend liveness probe timeout to 30s to allow the application to start before being killed.",
  "rationale": "The application takes 32s to start (from 10:26:10Z to 10:26:42Z in logs) but the liveness probe times out after 1s. The logs show it's still loading data when killed by SIGTERM. Extending the liveness timeout to 30s would let the app finish startup before being terminated.",
  "cited_evidence_ids": ["ev-container_logs_tail", "ev-rollout_history", "ev-pod_states", "ev-target_events"],
  "cited_predicates": ["probe_kills", "killed_during_startup"]
}
}
